# Fixture 1: OpenAI inclusive input-token usage
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_01_openai_inclusive_input_usage():
    # OpenAI reports total input in prompt_tokens
    msg = AIMessage(
        content="OpenAI normal response",
        usage_metadata={
            "input_tokens": 1000,
            "output_tokens": 150,
            "total_tokens": 1150,
        },
    )
    usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "gpt-4o")
    breakdown = usage.to_breakdown()
    assert breakdown.total_input_tokens == 1000
    assert breakdown.uncached_input_tokens == 1000
    assert breakdown.cached_tokens == 0
    assert breakdown.cache_write_tokens == 0
    assert breakdown.output_tokens == 150
    assert breakdown.is_conserved()


# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
# Fixture 2: OpenAI cached input
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_02_openai_cached_input():
    # OpenAI prompt_tokens is inclusive (1000), cached is 400, uncached is 600
    msg = AIMessage(
        content="OpenAI cached response",
        usage_metadata={
            "input_tokens": 1000,
            "output_tokens": 200,
            "total_tokens": 1200,
            "input_token_details": {
                "cache_read": 400,
            },
        },
    )
    usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "gpt-4o")
    breakdown = usage.to_breakdown()
    assert breakdown.total_input_tokens == 1000
    assert breakdown.uncached_input_tokens == 600
    assert breakdown.cached_tokens == 400
    assert breakdown.cache_write_tokens == 0
    assert breakdown.output_tokens == 200
    assert breakdown.is_conserved()

    # Cost: 600 uncached @ 2.50 = 0.0015, 400 cached @ 1.25 = 0.0005, 200 out @ 10.00 = 0.002
    # Total = 0.0040
    cost, curr = estimate_cost_from_rate(
        "gpt-4o",
        input_tokens=usage.prompt_tokens,
        output_tokens=usage.completion_tokens,
        cached_tokens=usage.cached_tokens,
        cache_reported=True,
        rate_card=OPENAI_GPT4O_RATES,
    )
    assert round(cost, 6) == 0.004


