    usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "claude-3-5-sonnet")
    breakdown = usage.to_breakdown()
    assert breakdown.total_input_tokens == 1550
    assert breakdown.uncached_input_tokens == 50
    assert breakdown.cached_tokens == 1500
    assert breakdown.cache_write_tokens == 0
    assert breakdown.output_tokens == 200
    assert breakdown.is_conserved()


