# Fixture 8: Missing provider usage fields
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_08_missing_provider_usage_fields():
    # Provider reports empty/null metadata
    msg = AIMessage(content="Hello world response with no usage metadata")
    usage = TokenTracker.record_call([HumanMessage(content="Hello")], msg, "claude-3-5-sonnet")
    # Should fall back to tokenizer estimation without raising
    assert usage.prompt_tokens > 0
    assert usage.completion_tokens > 0
    assert usage.total_tokens == usage.prompt_tokens + usage.completion_tokens
    assert usage.cached_tokens == 0
    assert usage.cache_write_tokens == 0
    assert usage.to_breakdown().is_conserved()


