# Fixture 9: Malformed token counts
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_09_malformed_token_counts():
    # Provider returns booleans, strings or negative counts in freeform metadata
    msg = AIMessage(
        content="Malformed usage in response_metadata",
        response_metadata={
            "token_usage": {
                "input_tokens": 500,
                "output_tokens": 50,
                "prompt_tokens_details": {
                    "cached_tokens": "not_a_number",
                    "cache_write": False,  # booleans must be ignored
                },
            }
        },
    )
    usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "gpt-4o")
    assert usage.prompt_tokens == 500
    assert usage.cached_tokens == 0
    assert usage.cache_write_tokens == 0
    assert usage.to_breakdown().is_conserved()


