# Fixture 10: Streaming usage followed by final usage (deduplication)
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_10_streaming_deduplication():
    # Intermediate streaming chunks carry partial or repeated usage.
    # The final chunk carries the ground truth cumulative total.
    chunk1 = AIMessageChunk(
        content="Hello",
        usage_metadata={"input_tokens": 100, "output_tokens": 1, "total_tokens": 101},
    )
    chunk2 = AIMessageChunk(
        content=" world",
        usage_metadata={"input_tokens": 100, "output_tokens": 2, "total_tokens": 102},
    )
    final_chunk = AIMessageChunk(
        content="!",
        usage_metadata={
            "input_tokens": 100,
            "output_tokens": 3,
            "total_tokens": 103,
            "input_token_details": {"cache_read": 80},
        },
    )

    chunks = [chunk1, chunk2, final_chunk]
    dedup = deduplicate_streaming_usage(chunks)
    assert dedup is not None
    # Crucial: Must be 100 total input tokens, NOT 300 (sum of chunks)
    assert dedup["input_tokens"] == 100
    assert dedup["output_tokens"] == 3
    assert dedup["cached_tokens"] == 80
    assert dedup["uncached_tokens"] == 20


# -----------------------------------------------------------------------------
# Fixture 11: Session persistence and recovery of normalized counters
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_11_session_persistence_and_recovery(tmp_path):
    db_file = str(tmp_path / "fin_norm.db")
    store = FinancialStore(db_file)
    gov = CostGovernor(
        CostGovernanceConfig(
            per_session_cost_budget_inr=Decimal("1000.00"),
            per_turn_cost_budget_inr=Decimal("500.00"),
        ),
        store=store,
    )
    session_id = "test-session-norm-rec"

    # Turn 1: Anthropic response with cache reads & 5m write
    msg = AIMessage(
        content="Turn 1 response",
        response_metadata={
            "model": "claude-3-5-sonnet",
            "usage": {
                "input_tokens": 200,  # uncached remainder
                "output_tokens": 100,
                "cache_read_input_tokens": 1500,
                "cache_creation_input_tokens": 300,
                "cache_creation": {
                    "ephemeral_5m_input_tokens": 300,
                },
            },
        },
    )
    call_usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "claude-3-5-sonnet")
    assert call_usage.prompt_tokens == 2000  # 200 + 1500 + 300
    assert call_usage.cached_tokens == 1500
    assert call_usage.cache_write_tokens == 300
    assert call_usage.cache_write_5m_tokens == 300
    assert call_usage.uncached_tokens == 200

    gov.record_call(
        session_id=session_id,
        provider="anthropic",
        model="claude-3-5-sonnet",
        tier="standard",
        usage=call_usage,
    )

    tracker = gov.get_tracker(session_id)
    assert tracker.session_tokens == 2100
    assert tracker.session_cached_tokens == 1500
    assert tracker.session_cache_write_tokens == 300

    # Simulate restart
    fresh_gov = CostGovernor(
        CostGovernanceConfig(),
        store=FinancialStore(db_file),
    )
    restored = fresh_gov.get_tracker(session_id)
    assert restored.session_tokens == 2100
    assert restored.session_cached_tokens == 1500
    assert restored.session_cache_write_tokens == 300


# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
# Fixture 12: Mixed cache categories with exact token conservation
# # -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# -----------------------------------------------------------------------------# ------------------------------------------------------------------------------
def test_fixture_12_mixed_cache_categories_token_conservation():
    # Model response with all 4 categories:
    # total input: 10,000
    # cached: 6,000
    # 5m write: 2,000
    # 1h write: 1,000
    # uncached remainder: 10,000 - 6,000 - 2,000 - 1,000 = 1,000
    # output: 500
    msg = AIMessage(
        content="Complex mixed cache response",
        response_metadata={
            "model": "claude-3-5-sonnet",
            "usage": {
                "input_tokens": 1000,
                "output_tokens": 500,
                "cache_read_input_tokens": 6000,
                "cache_creation_input_tokens": 3000,
                "cache_creation": {
                    "ephemeral_5m_input_tokens": 2000,
                    "ephemeral_1h_input_tokens": 1000,
                },
            },
        },
    )
    usage = TokenTracker.record_call([HumanMessage(content="hi")], msg, "claude-3-5-sonnet")
    b = usage.to_breakdown()
    assert b.total_input_tokens == 10_000
    assert b.uncached_input_tokens == 1_000
    assert b.cached_tokens == 6_000
    assert b.cache_write_tokens == 3_000
    assert b.cache_write_5m_tokens == 2_000
    assert b.cache_write_1h_tokens == 1_000
    assert b.output_tokens == 500
    assert b.is_conserved()

    # Exact cost reconciliation:
    # 1,000 uncached @ $3.00/1M = $0.00300
    # 6,000 cached @ $0.30/1M = $0.00180
    # 2,000 5m write @ $3.75/1M = $0.00750
    # 1,000 1h write @ $6.00/1M = $0.00600
    # 500 output @ $15.00/1M = $0.00750
    # Total = 0.00300 + 0.00180 + 0.00750 + 0.00600 + 0.00750 = $0.02580
    cost, curr = estimate_cost_from_rate(
        "claude-3-5-sonnet",
        input_tokens=b.total_input_tokens,
        output_tokens=b.output_tokens,
        cached_tokens=b.cached_tokens,
        cache_reported=True,
        cache_write_tokens=b.cache_write_tokens,
        cache_write_reported=True,
        cache_write_5m_tokens=b.cache_write_5m_tokens,
        cache_write_1h_tokens=b.cache_write_1h_tokens,
        rate_card=ANTHROPIC_CLAUDE_RATES,
    )
    assert curr == "USD"
    assert round(cost, 6) == 0.02580
